var i=`0649-fataya`;var t=`world-0649`;var a=`SN`;var o=`western-africa`;var r=8;var s=75;var l={en:`Fataya`,ua:`Фатая`};var g={en:`Fataya is a Senegal classic prepared with all-purpose flour, ground beef, yellow onion, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Фатая, страва кухні країни Сенегал зі складниками: пшеничне борошно універсальне, яловичий фарш, жовта цибуля, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 20 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 20 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:20,i:[[`all-purpose-flour`,460,`g`],[`water`,220,`ml`],[`unsalted-butter`,70,`g`],[`table-salt`,5,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:13,i:[[`ground-beef`,480,`g`],[`yellow-onion`,190,`g`],[`tomato`,140,`g`],[`parsley`,20,`g`],[`ground-cumin`,6,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:16,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 23 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 23 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:23,i:[[`sunflower-oil`,800,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lemon`,1,`pcs`]]}];var d={slug:i,id:t,country:`SN`,region:o,servings:8,minutes:75,title:l,text:g,steps:u};export{a as country,d as default,t as id,s as minutes,o as region,r as servings,i as slug,u as steps,g as text,l as title};